// Shared PDF helpers for the interview summary tests.
//
// The shipped browser bundles (js/vendor) and fonts (assets/fonts) are the
// ones under test: they are loaded here exactly as the page loads them, and
// text is read back out of the generated bytes through each font's ToUnicode
// map, the same route a PDF reader's copy and search take.

import { readFileSync } from 'node:fs';

const ROOT = new URL('../../../../../', import.meta.url);

function loadUmd(path) {
  const module = { exports: {} };
  new Function('exports', 'module', 'define', readFileSync(new URL(path, ROOT), 'utf8'))
    .call(globalThis, module.exports, module, undefined);
  return module.exports;
}

let cached = null;
export function loadPdfDeps() {
  if (!cached) {
    cached = {
      PDFLib: loadUmd('js/vendor/pdf-lib.min.js'),
      fontkit: loadUmd('js/vendor/fontkit.umd.min.js'),
      fonts: {
        regular: readFileSync(new URL('assets/fonts/Inter-Regular.ttf', ROOT)),
        bold: readFileSync(new URL('assets/fonts/Inter-Bold.ttf', ROOT))
      }
    };
  }
  return cached;
}

export function fontBytes(name) {
  const bytes = readFileSync(new URL('assets/fonts/' + name, ROOT));
  return bytes.buffer.slice(bytes.byteOffset, bytes.byteOffset + bytes.byteLength);
}

const latin1 = (bytes) => Buffer.from(bytes).toString('latin1');

function unicodeMap(PDFLib, fontDict) {
  const stream = fontDict.lookup(PDFLib.PDFName.of('ToUnicode'));
  const cmap = latin1(PDFLib.decodePDFRawStream(stream).decode());
  const map = new Map();
  for (const block of cmap.match(/beginbfchar[\s\S]*?endbfchar/g) || []) {
    for (const m of block.matchAll(/<([0-9A-Fa-f]+)>\s*<([0-9A-Fa-f]+)>/g)) {
      const units = m[2].match(/.{4}/g).map((h) => parseInt(h, 16));
      map.set(m[1].toUpperCase(), String.fromCharCode(...units));
    }
  }
  if (/beginbfrange/.test(cmap)) throw new Error('pdf-test-kit: bfrange maps are not handled');
  return map;
}

/**
 * @returns {Promise<{pageCount: number, pages: string[], text: string, info: object}>}
 *   pages[i] is that page's drawn text, one space between drawn pieces.
 */
export async function readPdf(bytes) {
  const { PDFLib } = loadPdfDeps();
  const doc = await PDFLib.PDFDocument.load(bytes);
  const pages = doc.getPages().map((page) => {
    const fonts = new Map();
    const fontDict = page.node.Resources().lookup(PDFLib.PDFName.of('Font'));
    for (const [name, ref] of fontDict.entries()) {
      fonts.set(name.asString().replace(/^\//, ''), unicodeMap(PDFLib, doc.context.lookup(ref)));
    }
    const contents = page.node.Contents();
    const streams = typeof contents.size === 'function'
      ? Array.from({ length: contents.size() }, (_, i) => contents.lookup(i)) : [contents];
    const pieces = [];
    let current = null;
    for (const stream of streams) {
      const ops = latin1(PDFLib.decodePDFRawStream(stream).decode());
      for (const m of ops.matchAll(/\/(\S+)\s+[\d.]+\s+Tf|<([0-9A-Fa-f]+)>\s*Tj/g)) {
        if (m[1]) { current = fonts.get(m[1]); continue; }
        const glyphs = m[2].toUpperCase().match(/.{4}/g) || [];
        pieces.push(glyphs.map((g) => {
          if (!current || !current.has(g)) throw new Error('pdf-test-kit: glyph ' + g + ' has no Unicode mapping');
          return current.get(g);
        }).join(''));
      }
    }
    return pieces.join(' ');
  });
  return {
    pageCount: pages.length,
    pages,
    text: pages.join(' '),
    info: { title: doc.getTitle(), author: doc.getAuthor(), subject: doc.getSubject(), producer: doc.getProducer() }
  };
}
